Real-Time Scoring Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(real_time_scoring_engine, "Real-Time Scoring Engine") {
    Component(HTTP_Request_Handler, "HTTP Request Handler", "Go (net/http)", "Receives authorization scoring requests via HTTPS/REST with mTLS from Amazon API Gateway.")
    Component(Fraud_Scoring_Orchestrator, "Fraud Scoring Orchestrator", "Go", "Evaluates transactions against real-time constraints, delivering sub-50ms P99 latency.")
    Component(Model_Inference_Engine, "Model Inference Engine", "ONNX Runtime", "Executes cryptographically signed models retrieved from the Model Registry.")
}

Rel(HTTP_Request_Handler, Fraud_Scoring_Orchestrator, "Forwards incoming authorization requests for evaluation")
Rel(Fraud_Scoring_Orchestrator, Model_Inference_Engine, "Invokes model scoring using loaded machine learning models")

@startuml

Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database container

Container_Boundary(database_container, "Database") {
    Component(PgBouncer Connection Pooler, "PgBouncer Connection Pooler", "PgBouncer", "Manages and optimizes database connections to support cost-efficient scalability and high concurrency.")
    Component(Relational Storage Engine, "Relational Storage Engine", "Amazon Aurora PostgreSQL Serverless v2", "Stores relational case data, dynamic rules, and model metadata with strict schema boundaries.")
}

Rel(PgBouncer Connection Pooler, Relational Storage Engine, "Forwards pooled SQL queries over TLS 1.3", "TCP/5432")

@enduml

Messaging & Audit Pipeline.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Messaging & Audit Pipeline container

Container_Boundary("Messaging & Audit Pipeline", "Messaging & Audit Pipeline") {
  Component(MessageQueue, "Message Queue", "Amazon SQS", "Buffers asynchronous events and logs generated by the Real-Time Scoring Engine.")
  Component(AuditLogger, "Audit Logger", "Amazon S3 with Object Lock", "Writes tamper-evident, 7-year audit logs in Compliance Mode.")
}

Rel(MessageQueue, AuditLogger, "Forwards asynchronous events and logs for persistent immutable storage", "")

@enduml

Network & Security.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(network_security, "Network & Security") {
    Component(AWS_WAF_API_Gateway, "AWS WAF & API Gateway", "Amazon API Gateway, AWS WAF", "Handles edge routing, request filtering for high-throughput traffic, and securing entry points.")
    Component(AWS_KMS_Secrets_Manager, "AWS KMS & Secrets Manager", "AWS KMS, AWS Secrets Manager", "Manages encryption, key segregation, and automated credential rotation for PCI-DSS compliance.")
    Component(AWS_VPC_Security_Groups, "AWS VPC Security Groups", "AWS VPC Security Groups", "Enforces micro-segmentation ensuring strict network isolation.")
}

Rel(AWS_WAF_API_Gateway, AWS_VPC_Security_Groups, "Filters and routes traffic through secured network boundaries", "")
Rel(AWS_KMS_Secrets_Manager, AWS_VPC_Security_Groups, "Secures data access across isolated network segments via AWS IAM", "")
@enduml
